create or replace function public.admin_assign_unit_access(target_profile_id uuid,target_unit_id uuid,new_assignment_role public.organization_assignment_role,allow_manage boolean default false,allow_sensitive boolean default false) returns uuid language plpgsql security definer set search_path='' as $$ declare result_id uuid; begin if not public.is_admin() then raise exception 'Accès administrateur requis'; end if; if not exists(select 1 from public.profiles p where p.id=target_profile_id and p.active=true and p.access_status='approved') then raise exception 'Le compte doit être approuvé'; end if; select a.id into result_id from public.profile_unit_assignments a where a.profile_id=target_profile_id and a.organization_unit_id=target_unit_id and a.assignment_role=new_assignment_role limit 1; if result_id is null then insert into public.profile_unit_assignments(profile_id,organization_unit_id,assignment_role,active,can_manage,can_view_sensitive) values(target_profile_id,target_unit_id,new_assignment_role,true,allow_manage,allow_sensitive) returning id into result_id; else update public.profile_unit_assignments set active=true,can_manage=allow_manage,can_view_sensitive=allow_sensitive,updated_at=now() where id=result_id; end if; return result_id; end; $$; revoke all on function public.admin_assign_unit_access(uuid,uuid,public.organization_assignment_role,boolean,boolean) from public,anon; grant execute on function public.admin_assign_unit_access(uuid,uuid,public.organization_assignment_role,boolean,boolean) to authenticated;